// TypeScript declarations from the JSON Schema subset schema-gen writes: $defs, $ref, objects with properties, maps by
// propertyNames, arrays and fixed-length tuples, enums, consts, anyOf and oneOf, and `^x-` note keys.

type Schema = { [key: string]: unknown };

const header =
  "// Generated by `node kit/tools/gen-types.ts` from schema/recipe.schema.json; `./gradlew generateSchemas` runs it too.\n" +
  "// Do not edit: `node kit/tools/gen-types.ts --check` fails when this file and the schema differ.\n";

export function generateTypes(root: Schema): string {
  const defs = (root.$defs ?? {}) as Record<string, Schema>;
  const blocks = Object.keys(defs)
    .sort()
    .map((name) => declaration(name, defs[name]));
  const rootRef = typeof root.$ref === "string" ? refName(root.$ref) : undefined;
  if (rootRef) blocks.push(`/** The document schema/recipe.schema.json describes. */\nexport type RecipeDocument = ${rootRef};`);
  return header + "\n" + blocks.join("\n\n") + "\n";
}

function declaration(name: string, schema: Schema): string {
  const doc = docComment(schema.description, "");
  if (isObjectWithProperties(schema)) return `${doc}export interface ${name} ${objectBody(schema, "")}`;
  return `${doc}export type ${name} = ${typeOf(schema, "")};`;
}

function docComment(description: unknown, indent: string): string {
  if (typeof description !== "string" || description.length === 0) return "";
  return `${indent}/** ${description.replaceAll("*/", "*\\/")} */\n`;
}

function refName(ref: string): string {
  return ref.slice(ref.lastIndexOf("/") + 1);
}

function isObjectWithProperties(schema: Schema): boolean {
  return schema.type === "object" && typeof schema.properties === "object";
}

function typeOf(schema: Schema, indent: string): string {
  if (typeof schema.$ref === "string") return refName(schema.$ref);
  if (Array.isArray(schema.enum)) return schema.enum.map((value) => JSON.stringify(value)).join(" | ");
  if ("const" in schema) return JSON.stringify(schema.const);
  const union = (schema.anyOf ?? schema.oneOf) as Schema[] | undefined;
  if (union) return union.map((member) => wrap(typeOf(member, indent))).join(" | ");
  if (Array.isArray(schema.type)) return schema.type.map((type) => typeOf({ ...schema, type }, indent)).join(" | ");
  switch (schema.type) {
    case "string":
      return "string";
    case "number":
    case "integer":
      return "number";
    case "boolean":
      return "boolean";
    case "null":
      return "null";
    case "array":
      return arrayType(schema, indent);
    case "object":
      return isObjectWithProperties(schema) ? objectBody(schema, indent) : mapType(schema, indent);
    default:
      return "unknown";
  }
}

function wrap(type: string): string {
  return type.includes(" | ") && !type.startsWith("{") ? `(${type})` : type;
}

function arrayType(schema: Schema, indent: string): string {
  const item = schema.items ? typeOf(schema.items as Schema, indent) : "unknown";
  const length = schema.minItems;
  if (typeof length === "number" && length === schema.maxItems) return `[${Array(length).fill(item).join(", ")}]`;
  return `${wrap(item)}[]`;
}

function mapType(schema: Schema, indent: string): string {
  const value = schema.additionalProperties;
  const valueType = typeof value === "object" && value !== null ? typeOf(value as Schema, indent) : "unknown";
  const keys = (schema.propertyNames as Schema | undefined)?.enum;
  if (Array.isArray(keys)) return `{ ${keys.map((key) => `${key}?: ${valueType}`).join("; ")} }`;
  return `{ [key: string]: ${valueType} }`;
}

function objectBody(schema: Schema, indent: string): string {
  const inner = indent + "  ";
  const required = new Set((schema.required ?? []) as string[]);
  const lines = Object.entries(schema.properties as Record<string, Schema>).map(([key, property]) => {
    const name = /^[A-Za-z_][A-Za-z0-9_]*$/.test(key) ? key : JSON.stringify(key);
    const optional = required.has(key) ? "" : "?";
    return `${docComment(property.description, inner)}${inner}${name}${optional}: ${typeOf(property, inner)};`;
  });
  const patterns = Object.keys((schema.patternProperties ?? {}) as Schema);
  if (patterns.includes("^x-")) lines.push(`${inner}/** A note the build reads past. */\n${inner}[note: \`x-\${string}\`]: unknown;`);
  return `{\n${lines.join("\n")}\n${indent}}`;
}
